// ------------------------------------------------------
// Main function: build polygons from unordered line segs
// ------------------------------------------------------
function extractPolysFromLines(lines) {
	let polys = [];

	for (let seg of lines) {
		let p1 = {
			x: seg.x1,
			y: seg.y1,
			z: seg.z
		};
		let p2 = {
			x: seg.x2,
			y: seg.y2,
			z: seg.z
		};

		// Try to connect to an existing polygon
		let found = false;

		for (let poly of polys) {
			// Check start of polygon
			if (near(p1, poly[0])) {
				poly.unshift(p2);
				found = true;
				break;
			}
			if (near(p2, poly[0])) {
				poly.unshift(p1);
				found = true;
				break;
			}

			// Check end of polygon
			let last = poly[poly.length - 1];
			if (near(p1, last)) {
				poly.push(p2);
				found = true;
				break;
			}
			if (near(p2, last)) {
				poly.push(p1);
				found = true;
				break;
			}
		}

		// No match found → create a new polygon
		if (!found) {
			polys.push([p1, p2]);
		}
	}

	// Optional: attempt closing polygons
	closePolygons(polys);

	return polys;
}

// ------------------------------------------------------
// Check if two points are "near" (within EPS)
// ------------------------------------------------------
function near(a, b, eps = 0.01) {
	if (abs(a.z-b.z) > eps) return false;
	let dx = a.x - b.x;
	let dy = a.y - b.y;
	return dx * dx + dy * dy <= eps * eps;
}

// ------------------------------------------------------
// Attempt to close polygons if endpoints match
// ------------------------------------------------------
function closePolygons(polys) {
	for (let poly of polys) {
		let first = poly[0];
		var last = poly[poly.length - 1];

		if (near(first, last)) {
			// Snap to perfect closure
			poly[poly.length - 1] = {
				...first
			};
		}
	}
}

// ------------------------------------------------------
// OPTIONAL — Merge polygons if endpoints match
// (Useful when contour extraction produces fragments)
// ------------------------------------------------------
function connectPolygons(polys) {
	let changed = true;

	while (changed) {
		changed = false;

		for (let i = 0; i < polys.length; i++) {
			for (let j = i + 1; j < polys.length; j++) {

				let A = polys[i];
				let B = polys[j];

				let Astart = A[0];
				let Aend = A[A.length - 1];
				let Bstart = B[0];
				let Bend = B[B.length - 1];

				// Various ways polygons can connect
				if (near(Aend, Bstart)) {
					A.push(...B.slice(1));
					polys.splice(j, 1);
					changed = true;
					break;
				} else if (near(Aend, Bend)) {
					A.push(...B.slice(0, B.length - 1).reverse());
					polys.splice(j, 1);
					changed = true;
					break;
				} else if (near(Astart, Bstart)) {
					A.unshift(...B.slice(1).reverse());
					polys.splice(j, 1);
					changed = true;
					break;
				} else if (near(Astart, Bend)) {
					A.unshift(...B.slice(0, B.length - 1));
					polys.splice(j, 1);
					changed = true;
					break;
				}
			}
		}
	}

	// Re-close after merging
	closePolygons(polys);

	return polys;
}


function consolidatePolygons(polys, eps = 0.001) {

  var changed = true;

  while (changed) {
    changed = false;

    for (let i = 0; i < polys.length; i++) {
      var A = polys[i];
      var Astart = A[0];
      var Aend   = A[A.length - 1];

      for (let j = 0; j < polys.length; j++) {
        if (i === j) continue;

        var B = polys[j];
        var Bstart = B[0];
        var Bend   = B[B.length - 1];

        // --------------------------------------
        // CASE 1: A.end → B.start
        // A ... Aend == Bstart ... B
        // --------------------------------------
        if (near(Aend, Bstart, eps)) {
          A.push(...B.slice(1));     // skip duplicate Bstart
          polys.splice(j, 1);
          changed = true;
          break;
        }

        // --------------------------------------
        // CASE 2: A.end → B.end  (reverse B)
        // A ... Aend == Bend ... B_reversed
        // --------------------------------------
        if (near(Aend, Bend, eps)) {
          B.reverse();
          A.push(...B.slice(1));     // skip duplicate
          polys.splice(j, 1);
          changed = true;
          break;
        }

        // --------------------------------------
        // CASE 3: A.start → B.end
        // B ... Bend == Astart ... A
        // --------------------------------------
        if (near(Astart, Bend, eps)) {
          A.unshift(...B.slice(0, B.length - 1));
          polys.splice(j, 1);
          changed = true;
          break;
        }

        // --------------------------------------
        // CASE 4: A.start → B.start  (reverse B)
        // B_reversed ... Bstart == Astart ... A
        // --------------------------------------
        if (near(Astart, Bstart, eps)) {
          B.reverse();
          A.unshift(...B.slice(1));  // skip duplicate
          polys.splice(j, 1);
          changed = true;
          break;
        }
      }

      if (changed) break;
    }
  }

  return polys;
}


function closeLoosePolygons(polys, spacing, eps) {
  for (let poly of polys) {

    if (poly.length < 3) continue; // can't close tiny shapes

    var first = poly[0];
    var last  = poly[poly.length - 1];

    var dx = last.x - first.x;
    var dy = last.y - first.y;
	 let dz = last.z - first.z;
    let d2 = dx*dx + dy*dy;
    let dst = Math.sqrt(d2);

    // Rule:
    // if eps < distance < spacing → close polygon
    if (dst < spacing && dst > eps && abs(dz) < eps) {
      poly.push({ x: first.x, y: first.y, z: first.z });
    }
  }

  return polys;
}



function splitPolygons(polys, minSteps, maxSteps) {
  let result = [];

  for (let poly of polys) {
    let i = 0;

    while (i < poly.length) {

      // pick a random step size for this piece
      let steps = floor(random(minSteps, maxSteps + 1));

      // ensure we don't exceed polygon length
      let end = i + steps;
      if (end > poly.length) end = poly.length;

      // slice the polygon segment
      let segment = poly.slice(i, end);

      // only keep meaningful segments (min 2 points)
      if (segment.length >= 2) {
        result.push(segment);
      }

      i = end;
    }
  }

  return result;
}


