// Smooth Topographic Map with Soft Marching Squares

let grid, cols, rows;
let spacing = 9; // larger spacing = bigger/faster contour segments
let noiseScale = 0.04; // noise frequency
let lines, polygons, areas;

function setup() {
	createCanvas(S = min(innerWidth, innerHeight), S);
	frameRate(30);
	// pixelDensity(1);
	// // noLoop() removed for animation

	cols = Math.ceil(width / spacing) + 1;
	rows = Math.ceil(height / spacing) + 1;

	grid = buildHeightmap();
	background("tan");

	stroke(0);
	strokeWeight(1);
	noFill();

	lines = [];

	// Draw multiple contour levels
	let levels = 30;
	for (let i = 0; i < levels; i++) {
		let level = i / levels; // thresholds from 0..1
		drawContour(level);
	}
	// console.log(lines.length, lines[0]);

	polygons = extractPolysFromLines(lines);
	polygons = consolidatePolygons(polygons, 0.01)
	polygons = closeLoosePolygons(polygons, spacing, 0.01)

	// areas
	const closedAreas = polygons.filter(poly => {
		if (poly.length < 3) return false;

		var first = poly[0];
		var last = poly[poly.length - 1];

		return near(first, last);
	});
	// console.log("closedAreas.length = " + closedAreas.length);

	areas = [];
	for (let i = 0; i < 5; i++) {
		areas.push([...random(closedAreas)])
	}
	areas.sort((firstItem, secondItem) => firstItem[0].z - secondItem[0].z);
	// console.log(areas)

	polygons.sort((firstItem, secondItem) => firstItem[0].z - secondItem[0].z);
	polygons = splitPolygons(polygons, 5, 9)
	// console.log(polygons.length, polygons[0], polygons);
}

function draw() {
	const t = millis() / 1000;
	fill("lightblue")
	noStroke();
	for (const poly of areas) {
		beginShape();
		for (const p of poly) vertex(p.x, p.y)
		endShape(CLOSE);
	}

	stroke("navy")
	noFill();
	for (const poly of polygons) {
		// stroke(random(222), random(222), random(222))
		// stroke(lerpColor(color("white"), color("black"), fract(poly[0].z+t)))
		beginShape();
		for (const p of poly) vertex(p.x, p.y)
		endShape();
	}

	// // noLoop() removed for animation
}

// --------------------------------------------------
// 1. Build the heightmap (Perlin noise)
// --------------------------------------------------
function buildHeightmap() {
	let g = [];
	for (let y = 0; y < rows; y++) {
		g[y] = [];
		for (let x = 0; x < cols; x++) {
			g[y][x] = noise(x * noiseScale, y * noiseScale);
		}
	}
	return g;
}

// --------------------------------------------------
// 2. Marching Squares for a single contour level
// --------------------------------------------------
function drawContour(level) {
	for (let y = 0; y < rows - 1; y++) {
		for (let x = 0; x < cols - 1; x++) {

			let a = grid[y][x] > level;
			let b = grid[y][x + 1] > level;
			let c = grid[y + 1][x + 1] > level;
			let d = grid[y + 1][x] > level;

			let state = (a << 3) | (b << 2) | (c << 1) | d;

			let e1 = interp(x, y, x + 1, y, level);
			let e2 = interp(x + 1, y, x + 1, y + 1, level);
			let e3 = interp(x, y + 1, x + 1, y + 1, level);
			let e4 = interp(x, y, x, y + 1, level);

			switch (state) {
				case 1:
				case 14:
					lineSeg(e3, e4, level);
					break;
				case 2:
				case 13:
					lineSeg(e2, e3, level);
					break;
				case 3:
				case 12:
					lineSeg(e2, e4, level);
					break;
				case 4:
				case 11:
					lineSeg(e1, e2, level);
					break;
				case 5:
					lineSeg(e1, e4, level);
					lineSeg(e2, e3, level);
					break;
				case 6:
				case 9:
					lineSeg(e1, e3, level);
					break;
				case 7:
				case 8:
					lineSeg(e1, e4, level);
					break;
				case 10:
					lineSeg(e1, e2, level);
					lineSeg(e3, e4, level);
					break;
			}
		}
	}
}

// --------------------------------------------------
// 3. Smoothed interpolation (soft marching squares)
// --------------------------------------------------
function interp(x1, y1, x2, y2, level) {
	let v1 = grid[y1][x1];
	let v2 = grid[y2][x2];

	let denom = (v2 - v1);

	// If values are too close, return midpoint directly
	if (abs(denom) < 0.000001) {
		return createVector(
			(x1 + x2) * 0.5 * spacing,
			(y1 + y2) * 0.5 * spacing,
			level
		);
	}

	// Regular t
	var t = (level - v1) / denom;

	// Clamp to a valid range BEFORE smoothing
	t = constrain(t, 0, 1);

	// Smooth it
	// t = pow(t, 0.7);

	// Convert grid coords to pixel coords
	let px1 = x1 * spacing;
	let py1 = y1 * spacing;
	let px2 = x2 * spacing;
	let py2 = y2 * spacing;

	return createVector(
		lerp(px1, px2, t),
		lerp(py1, py2, t),
		level
	);
}

// --------------------------------------------------
// Helper to safely draw a segment
// --------------------------------------------------
function lineSeg(a, b, level = 0) {
	if (!a || !b) return;
	// line(a.x, a.y, b.x, b.y);
	lines.push({
		x1: a.x,
		y1: a.y,
		x2: b.x,
		y2: b.y,
		z: level
	})
}
